import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce(torch::Tensor x, int64_t dim);
"""

min_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Collapsed contiguous reduction view:
//   X logical: (outer, R, inner) with strides (R*inner, inner, 1)
//   Y logical: (outer, inner)     with strides (inner, 1)
// This is exact for any contiguous input and any reduced dim.
template <int BM, int RS, int V>
__global__ void min_reduce_cute_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer, int R, int inner)
{
  const int tid   = threadIdx.x;
  const int lane  = tid % BM;       // output-column tile lane
  const int split = tid / BM;       // reduction split id
  // Register blocking over the contiguous `inner` dimension:
  // each thread computes V independent partial minima for columns
  // base + k*BM (k in [0,V)). This keeps every load coalesced across
  // the warp while giving each thread V independent load/accumulate
  // streams, raising memory-level parallelism and shrinking the grid
  // by a factor of V compared to one-output-per-thread.
  constexpr int BT = BM * V;
  const int tiles = (inner + BT - 1) / BT;
  const int lin   = blockIdx.x;
  const int o     = lin / tiles;
  const int t     = lin - o * tiles;
  const int base  = t * BT + lane;
  const int64_t sOuter = (int64_t)R * inner;
  const int64_t sRed   = (int64_t)inner;
  const int64_t sInner = 1;
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, R, inner),
      make_stride(sOuter, sRed, sInner));
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, inner),
      make_stride((int64_t)inner, (int64_t)1));
  __shared__ float sm[RS][BT];
  float acc[V];
  #pragma unroll
  for (int k = 0; k < V; ++k) {
    acc[k] = __int_as_float(0x7f800000); // +inf
  }
  // Strided split over R keeps each warp coalesced along `inner`.
  // Reduction-loop unrolling: each thread processes UR=4 row-groups per
  // iteration, issuing UR*V independent global loads before the fminf
  // dependency chains. This raises memory-level parallelism (more loads
  // in flight per thread) for this bandwidth-bound streaming reduction,
  // without changing the coalesced access pattern or the column mapping.
  constexpr int UR = 4;
  if (base + (V - 1) * BM < inner) {
    // Fast path: all V columns in bounds, no per-element checks.
    const float* __restrict__ po = X + (int64_t)o * sOuter + base;
    int r = split;
    for (; r + (UR - 1) * RS < R; r += UR * RS) {
      #pragma unroll
      for (int u = 0; u < UR; ++u) {
        const float* __restrict__ pu = po + (int64_t)(r + u * RS) * sRed;
        #pragma unroll
        for (int k = 0; k < V; ++k) {
          acc[k] = fminf(acc[k], __ldg(pu + k * BM));
        }
      }
    }
    for (; r < R; r += RS) {
      const float* __restrict__ pr = po + (int64_t)r * sRed;
      #pragma unroll
      for (int k = 0; k < V; ++k) {
        acc[k] = fminf(acc[k], __ldg(pr + k * BM));
      }
    }
  } else {
    // Tail path: guard each of the V columns.
    for (int r = split; r < R; r += RS) {
      #pragma unroll
      for (int k = 0; k < V; ++k) {
        const int i = base + k * BM;
        if (i < inner) {
          acc[k] = fminf(acc[k], mX(o, r, i));
        }
      }
    }
  }
  #pragma unroll
  for (int k = 0; k < V; ++k) {
    sm[split][k * BM + lane] = acc[k];
  }
  __syncthreads();
  if (split == 0) {
    #pragma unroll
    for (int k = 0; k < V; ++k) {
      const int i = base + k * BM;
      if (i < inner) {
        float m = sm[0][k * BM + lane];
        #pragma unroll
        for (int s = 1; s < RS; ++s) {
          m = fminf(m, sm[s][k * BM + lane]);
        }
        mY(o, i) = m;
      }
    }
  }
}

torch::Tensor min_reduce(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto xc = x.contiguous();
  const int64_t nd = xc.dim();
  TORCH_CHECK(nd >= 1, "x must have at least one dimension");

  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= xc.size(d);
  const int64_t R = xc.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < nd; ++d) inner *= xc.size(d);
  TORCH_CHECK(R > 0, "cannot reduce over an empty dimension");

  auto out_sizes = xc.sizes().vec();
  out_sizes.erase(out_sizes.begin() + dim);
  auto y = torch::empty(out_sizes, xc.options());
  if (y.numel() == 0) return y;

  constexpr int BM = 128;
  constexpr int RS = 4;
  constexpr int V  = 4;
  constexpr int BT = BM * V;
  constexpr int THREADS = BM * RS;
  const int64_t tiles = (inner + BT - 1) / BT;
  const int64_t blocks = outer * tiles;
  TORCH_CHECK(blocks > 0 && blocks < 2147483647LL, "invalid grid size");
  dim3 grid((unsigned)blocks);
  dim3 block(THREADS);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_cute_kernel<BM, RS, V><<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)R, (int)inner);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_cute_kernel failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=min_cpp_decl,
    cuda_sources=min_cuda_src,
    functions=["min_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Min reduction over a specified dimension using one custom CUTE/CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = int(dim)
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce(x, self.dim)

