  const int lin   = blockIdx.x;
  const int o     = lin / tiles;
  const int t     = lin - o * tiles;
  const int tBase = t * BT;
  const int64_t sOuter = (int64_t)R * inner;
  const int64_t sRed   = (int64_t)inner;
  const int64_t sInner = 1;
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, R, inner),
      make_stride(sOuter, sRed, sInner));
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, inner),
      make_stride((int64_t)inner, (int64_t)1));
  __shared__ float sm[RS][BT];
  const int64_t rowBase0 = ((int64_t)o * R + split) * (int64_t)inner;
  const int pad = (4 - (int)(rowBase0 & 3)) & 3;
  const int c = pad + lane * 4;      // first local column of this thread
  const int rowLen = inner - tBase;  // remaining columns in this tile
  const float INF = __int_as_float(0x7f800000); // +inf
  float acc[4] = {INF, INF, INF, INF};
  if (c < BT) {
    if (c + 3 < BT && c + 3 < rowLen) {
      // Fast path: aligned float4 loads, no per-element checks.
      const float* p = X + rowBase0 + tBase + c;
      const int64_t step = (int64_t)RS * inner;
      for (int r = split; r < R; r += RS) {
        const float4 v = *reinterpret_cast<const float4*>(p);
        acc[0] = fminf(acc[0], v.x);
        acc[1] = fminf(acc[1], v.y);
        acc[2] = fminf(acc[2], v.z);
        acc[3] = fminf(acc[3], v.w);
        p += step;
      }
    } else {
      // Tail path: scalar guarded loads.
      for (int r = split; r < R; r += RS) {
