  __syncthreads();
  if (split == 0) {
    int pads[RS];
    #pragma unroll
    for (int s = 0; s < RS; ++s) {
      const int64_t rb = ((int64_t)o * R + s) * (int64_t)inner;
      pads[s] = (4 - (int)(rb & 3)) & 3;
    }
    #pragma unroll
    for (int k = 0; k < 4; ++k) {
      const int j = lane * 4 + k;
