)


class ModelNew(nn.Module):
    """
    Min reduction over a specified dimension using one custom CUTE/CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = int(dim)
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce(x, self.dim)
